toolArgs.file_text:
@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Dispatcher Dashboard</h2>

<div class="row mt-3 mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-success" @onclick="ShowCreateForm">
            + New Shipment
        </button>
        <button class="btn btn-outline-secondary ms-2" @onclick="LoadShipments" disabled="@isLoading">
            ↻ Refresh
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-4">
                    <label class="form-label">Origin</label>
                    <input type="text" class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Destination</label>
                    <input type="text" class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Customer Email</label>
                    <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Description</label>
                    <input type="text" class="form-control" @bind="newShipment.Description" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Estimated Delivery</label>
                    <input type="date" class="form-control" @bind="estimatedDeliveryDate" />
                </div>
                <div class="col-12">
                    <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isCreating">
                        @if (isCreating) { <span class="spinner-border spinner-border-sm"></span> }
                        Create
                    </button>
                    <button class="btn btn-secondary ms-2" @onclick="CancelCreate">Cancel</button>
                </div>
            </div>
        </div>
    </div>
}

@if (isLoading)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            <select class="form-select form-select-sm d-inline-block w-auto"
                                    value="@s.Status"
                                    @onchange="(e) => UpdateStatus(s, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (!FilteredShipments.Any())
    {
        <p class="text-muted">No shipments match your filters.</p>
    }
}

@code {
    private List<Shipment> shipments = [];
    private bool isLoading = true;
    private bool showCreateForm;
    private bool isCreating;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;
    private Shipment newShipment = new();
    private DateTime? estimatedDeliveryDate;

    private IEnumerable<Shipment> FilteredShipments => shipments.Where(s =>
    {
        if (!string.IsNullOrWhiteSpace(filterText) &&
            !s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase))
            return false;

        if (!string.IsNullOrWhiteSpace(statusFilter) &&
            Enum.TryParse<ShipmentStatus>(statusFilter, out var status) &&
            s.Status != status)
            return false;

        return true;
    });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate()
    {
        showCreateForm = false;
        newShipment = new();
        estimatedDeliveryDate = null;
    }

    private async Task CreateShipment()
    {
        isCreating = true;
        try
        {
            newShipment.EstimatedDelivery = estimatedDeliveryDate;
            await ShipmentService.CreateShipmentAsync(newShipment);
            showCreateForm = false;
            newShipment = new();
            estimatedDeliveryDate = null;
            await LoadShipments();
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-info",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-warning text-dark"
    };
}

